import { useMemo, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useNutritionStore } from '@/stores/useNutritionStore';
import type { MacroPreset } from '@/stores/useNutritionStore';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Slider } from '@/components/ui/slider';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Progress } from '@/components/ui/progress';
import { PieChart, Pie, Cell, ResponsiveContainer } from 'recharts';
import {
  PieChartIcon,
  Beef,
  Wheat,
  Droplets,
  Trash2,
  Utensils,
  Droplets as DropletsIcon,
  Target,
} from 'lucide-react';

/* ------------------------------------------------------------------ */
/*  Constants                                                          */
/* ------------------------------------------------------------------ */

const PROTEIN_COLOR = '#00AEEF';
const CARBS_COLOR = '#10B981';
const FATS_COLOR = '#F59E0B';

const MACRO_PRESETS: { value: MacroPreset; label: string }[] = [
  { value: 'balanced', label: 'Balanced' },
  { value: 'low-carb', label: 'Low Carb' },
  { value: 'high-protein', label: 'High Protein' },
  { value: 'keto', label: 'Keto' },
];

const EASE_SMOOTH = [0.25, 0.1, 0.25, 1] as [number, number, number, number];

/* ------------------------------------------------------------------ */
/*  Component                                                          */
/* ------------------------------------------------------------------ */

export default function MacroRingPage() {
  const store = useNutritionStore();
  const [customMode, setCustomMode] = useState(false);
  const [customP, setCustomP] = useState(store.macroTargets.protein);
  const [customC, setCustomC] = useState(store.macroTargets.carbs);
  const [customF, setCustomF] = useState(store.macroTargets.fats);

  const todayISO = new Date().toISOString().split('T')[0];
  const todayLog = store.dailyLogs.find((l) => l.date === todayISO);

  // Consumed macros today
  const consumed = useMemo(() => {
    if (!todayLog) return { protein: 0, carbs: 0, fats: 0, calories: 0 };
    return todayLog.meals.reduce(
      (acc, m) => ({
        protein: acc.protein + m.protein,
        carbs: acc.carbs + m.carbs,
        fats: acc.fats + m.fats,
        calories: acc.calories + m.calories,
      }),
      { protein: 0, carbs: 0, fats: 0, calories: 0 }
    );
  }, [todayLog]);

  // Targets
  const targets = store.macroTargets;

  // Pie data
  const pieData = [
    { name: 'Protein', value: consumed.protein, target: targets.protein },
    { name: 'Carbs', value: consumed.carbs, target: targets.carbs },
    { name: 'Fats', value: consumed.fats, target: targets.fats },
  ];

  // If nothing consumed, show a placeholder ring
  const hasData = consumed.calories > 0;
  const displayPieData = hasData
    ? pieData
    : [
        { name: 'Protein', value: 1, target: targets.protein },
        { name: 'Carbs', value: 1, target: targets.carbs },
        { name: 'Fats', value: 1, target: targets.fats },
      ];

  const calPct = targets.calories > 0 ? Math.min(Math.round((consumed.calories / targets.calories) * 100), 100) : 0;

  // Progress percentages
  const pPct = Math.min(Math.round((consumed.protein / targets.protein) * 100), 100);
  const cPct = Math.min(Math.round((consumed.carbs / targets.carbs) * 100), 100);
  const fPct = Math.min(Math.round((consumed.fats / targets.fats) * 100), 100);

  // Custom slider handlers
  const applyCustom = (p: number, c: number, f: number) => {
    store.setCustomMacros({ protein: p, carbs: c, fats: f });
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, ease: EASE_SMOOTH }}
      >
        <h1 className="text-display-md text-gray-900 dark:text-white mb-1">Macro Ring</h1>
        <p className="text-body-md text-gray-500 dark:text-gray-400">
          Track your daily macro intake and hit your nutritional targets.
        </p>
      </motion.div>

      {/* Summary Stats Row */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, delay: 0.05, ease: EASE_SMOOTH }}
        className="grid grid-cols-2 sm:grid-cols-4 gap-3"
      >
        {[
          { label: 'Calories', value: `${consumed.calories} / ${targets.calories}`, pct: calPct, color: 'text-[#00AEEF]', icon: Target },
          { label: 'Protein', value: `${consumed.protein}g / ${targets.protein}g`, pct: pPct, color: 'text-[#00AEEF]', icon: Beef },
          { label: 'Carbs', value: `${consumed.carbs}g / ${targets.carbs}g`, pct: cPct, color: 'text-emerald-500', icon: Wheat },
          { label: 'Fats', value: `${consumed.fats}g / ${targets.fats}g`, pct: fPct, color: 'text-amber-500', icon: Droplets },
        ].map((s) => {
          const Icon = s.icon;
          return (
            <Card key={s.label} className="dark:bg-[#141414] dark:border-white/5">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 mb-2">
                  <Icon className={`w-4 h-4 ${s.color}`} />
                  <span className="text-xs text-gray-500 dark:text-gray-400">{s.label}</span>
                </div>
                <div className="text-data-sm text-gray-900 dark:text-white">{s.value}</div>
                <div className="mt-2 h-1 bg-gray-100 dark:bg-white/5 rounded-full overflow-hidden">
                  <motion.div
                    initial={{ width: 0 }}
                    animate={{ width: `${s.pct}%` }}
                    transition={{ duration: 0.6, ease: EASE_SMOOTH }}
                    className="h-full rounded-full"
                    style={{
                      backgroundColor:
                        s.label === 'Protein' || s.label === 'Calories'
                          ? PROTEIN_COLOR
                          : s.label === 'Carbs'
                            ? CARBS_COLOR
                            : FATS_COLOR,
                    }}
                  />
                </div>
              </CardContent>
            </Card>
          );
        })}
      </motion.div>

      {/* Main content: Donut + Details */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Donut Chart */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.1, ease: EASE_SMOOTH }}
        >
          <Card className="dark:bg-[#141414] dark:border-white/5 h-full">
            <CardHeader>
              <CardTitle className="text-heading-sm text-gray-900 dark:text-white flex items-center gap-2">
                <PieChartIcon className="w-5 h-5 text-[#00AEEF]" />
                Today&apos;s Breakdown
              </CardTitle>
              <CardDescription className="dark:text-gray-400">
                Calorie distribution by macro
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="relative" style={{ height: 280 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={displayPieData}
                      cx="50%"
                      cy="50%"
                      innerRadius={75}
                      outerRadius={110}
                      strokeWidth={3}
                      stroke="var(--card)"
                      dataKey="value"
                      animationBegin={0}
                      animationDuration={800}
                    >
                      <Cell fill={PROTEIN_COLOR} />
                      <Cell fill={CARBS_COLOR} />
                      <Cell fill={FATS_COLOR} />
                    </Pie>
                  </PieChart>
                </ResponsiveContainer>
                {/* Center text */}
                <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                  <AnimatePresence mode="wait">
                    <motion.div
                      key={consumed.calories}
                      initial={{ scale: 0.8, opacity: 0 }}
                      animate={{ scale: 1, opacity: 1 }}
                      exit={{ scale: 0.8, opacity: 0 }}
                      transition={{ duration: 0.3 }}
                      className="text-center"
                    >
                      <div className="text-data-lg text-gray-900 dark:text-white">
                        {consumed.calories}
                      </div>
                      <div className="text-xs text-gray-400">
                        / {targets.calories} kcal
                      </div>
                      <div className={`text-sm font-semibold mt-1 ${
                        calPct >= 100 ? 'text-emerald-500' : 'text-[#00AEEF]'
                      }`}>
                        {calPct}%
                      </div>
                    </motion.div>
                  </AnimatePresence>
                </div>
              </div>

              {/* Legend */}
              <div className="flex justify-center gap-6 mt-2">
                {[
                  { label: 'Protein', color: PROTEIN_COLOR, g: consumed.protein, t: targets.protein },
                  { label: 'Carbs', color: CARBS_COLOR, g: consumed.carbs, t: targets.carbs },
                  { label: 'Fats', color: FATS_COLOR, g: consumed.fats, t: targets.fats },
                ].map((item) => (
                  <div key={item.label} className="flex items-center gap-2">
                    <div className="w-3 h-3 rounded-full" style={{ backgroundColor: item.color }} />
                    <span className="text-xs text-gray-500 dark:text-gray-400">
                      {item.label} {item.g}g/{item.t}g
                    </span>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </motion.div>

        {/* Right column: Macro Cards */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.15, ease: EASE_SMOOTH }}
          className="space-y-4"
        >
          {/* Macro progress cards */}
          {[
            { label: 'Protein', consumed: consumed.protein, target: targets.protein, pct: pPct, color: PROTEIN_COLOR, icon: Beef, kcalPerGram: 4 },
            { label: 'Carbs', consumed: consumed.carbs, target: targets.carbs, pct: cPct, color: CARBS_COLOR, icon: Wheat, kcalPerGram: 4 },
            { label: 'Fats', consumed: consumed.fats, target: targets.fats, pct: fPct, color: FATS_COLOR, icon: Droplets, kcalPerGram: 9 },
          ].map((macro) => {
            const Icon = macro.icon;
            const remaining = Math.max(macro.target - macro.consumed, 0);
            return (
              <Card key={macro.label} className="dark:bg-[#141414] dark:border-white/5">
                <CardContent className="p-4">
                  <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center gap-2">
                      <div
                        className="w-8 h-8 rounded-lg flex items-center justify-center"
                        style={{ backgroundColor: `${macro.color}15` }}
                      >
                        <Icon className="w-4 h-4" style={{ color: macro.color }} />
                      </div>
                      <div>
                        <div className="text-sm font-semibold text-gray-900 dark:text-white">
                          {macro.label}
                        </div>
                        <div className="text-[10px] text-gray-400">
                          {macro.consumed * macro.kcalPerGram} kcal
                        </div>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-data-sm text-gray-900 dark:text-white">
                        {macro.consumed}<span className="text-xs text-gray-400">/{macro.target}g</span>
                      </div>
                    </div>
                  </div>
                  <Progress
                    value={macro.pct}
                    className="h-2.5 bg-gray-100 dark:bg-white/5"
                  />
                  <div className="flex justify-between mt-2">
                    <span className="text-[10px] text-gray-400">{macro.pct}%</span>
                    {remaining > 0 && (
                      <span className="text-[10px] text-gray-400">
                        {remaining}g remaining
                      </span>
                    )}
                    {remaining === 0 && macro.consumed >= macro.target && (
                      <span className="text-[10px] text-emerald-500 font-medium">Target reached!</span>
                    )}
                  </div>
                  {/* Override progress bar color via CSS custom property injected via style */}
                  <style>{`
                    div[data-slot="progress-indicator"] {
                      background-color: ${macro.color};
                    }
                  `}</style>
                </CardContent>
              </Card>
            );
          })}
        </motion.div>
      </div>

      {/* Preset Selector + Custom Editor */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, delay: 0.2, ease: EASE_SMOOTH }}
        className="grid grid-cols-1 lg:grid-cols-2 gap-6"
      >
        {/* Preset */}
        <Card className="dark:bg-[#141414] dark:border-white/5">
          <CardHeader>
            <CardTitle className="text-heading-sm text-gray-900 dark:text-white">Macro Preset</CardTitle>
            <CardDescription className="dark:text-gray-400">
              Choose a preset or customize your own
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <Select
              value={store.macroPreset}
              onValueChange={(v) => {
                if (v === 'custom') {
                  setCustomMode(true);
                } else {
                  setCustomMode(false);
                  store.setMacroPreset(v as MacroPreset);
                }
              }}
            >
              <SelectTrigger className="dark:bg-[#1A1A1A] dark:border-white/10 dark:text-white">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {MACRO_PRESETS.map((p) => (
                  <SelectItem key={p.value} value={p.value}>{p.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>

            {customMode && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                transition={{ duration: 0.3 }}
                className="space-y-4"
              >
                {/* Protein slider */}
                <div className="space-y-2">
                  <div className="flex justify-between">
                    <Label className="text-xs dark:text-gray-300">Protein</Label>
                    <span className="text-xs font-semibold text-[#00AEEF]">{customP}g</span>
                  </div>
                  <Slider
                    min={20}
                    max={400}
                    step={5}
                    value={[customP]}
                    onValueChange={([v]) => {
                      setCustomP(v);
                      applyCustom(v, customC, customF);
                    }}
                  />
                </div>
                {/* Carbs slider */}
                <div className="space-y-2">
                  <div className="flex justify-between">
                    <Label className="text-xs dark:text-gray-300">Carbs</Label>
                    <span className="text-xs font-semibold text-emerald-500">{customC}g</span>
                  </div>
                  <Slider
                    min={10}
                    max={600}
                    step={5}
                    value={[customC]}
                    onValueChange={([v]) => {
                      setCustomC(v);
                      applyCustom(customP, v, customF);
                    }}
                  />
                </div>
                {/* Fats slider */}
                <div className="space-y-2">
                  <div className="flex justify-between">
                    <Label className="text-xs dark:text-gray-300">Fats</Label>
                    <span className="text-xs font-semibold text-amber-500">{customF}g</span>
                  </div>
                  <Slider
                    min={10}
                    max={200}
                    step={5}
                    value={[customF]}
                    onValueChange={([v]) => {
                      setCustomF(v);
                      applyCustom(customP, customC, v);
                    }}
                  />
                </div>
                <div className="pt-2 text-center text-sm text-gray-600 dark:text-gray-300">
                  Custom total:{' '}
                  <span className="font-semibold text-[#00AEEF]">
                    {customP * 4 + customC * 4 + customF * 9}
                  </span>{' '}
                  kcal
                </div>
              </motion.div>
            )}
          </CardContent>
        </Card>

        {/* Quick Log Panel */}
        <Card className="dark:bg-[#141414] dark:border-white/5">
          <CardHeader>
            <CardTitle className="text-heading-sm text-gray-900 dark:text-white flex items-center gap-2">
              <Utensils className="w-4 h-4 text-[#00AEEF]" />
              Today&apos;s Meals
            </CardTitle>
            <CardDescription className="dark:text-gray-400">
              {todayLog ? `${todayLog.meals.length} meals logged` : 'No meals logged yet'}
              {todayLog && todayLog.waterIntake > 0 && (
                <span className="ml-2 inline-flex items-center gap-1 text-[#00AEEF]">
                  <DropletsIcon className="w-3 h-3" />
                  {todayLog.waterIntake} glasses
                </span>
              )}
            </CardDescription>
          </CardHeader>
          <CardContent>
            {todayLog && todayLog.meals.length > 0 ? (
              <div className="space-y-2 max-h-[280px] overflow-y-auto pr-1">
                <AnimatePresence>
                  {todayLog.meals.map((meal) => (
                    <motion.div
                      key={meal.id}
                      layout
                      initial={{ opacity: 0, x: -20 }}
                      animate={{ opacity: 1, x: 0 }}
                      exit={{ opacity: 0, x: 20 }}
                      transition={{ duration: 0.25 }}
                      className="flex items-center justify-between p-3 rounded-lg bg-gray-50 dark:bg-[#1A1A1A] group"
                    >
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="text-xs font-medium px-1.5 py-0.5 rounded bg-gray-200 dark:bg-white/10 text-gray-600 dark:text-gray-400 capitalize">
                            {meal.mealType}
                          </span>
                          <span className="text-sm font-medium text-gray-900 dark:text-white truncate">
                            {meal.name}
                          </span>
                        </div>
                        <div className="text-[10px] text-gray-400 mt-1 flex gap-2">
                          <span>{meal.calories} kcal</span>
                          <span>P:{meal.protein}g</span>
                          <span>C:{meal.carbs}g</span>
                          <span>F:{meal.fats}g</span>
                        </div>
                      </div>
                      <button
                        onClick={() => store.removeMealEntry(todayISO, meal.id)}
                        className="opacity-0 group-hover:opacity-100 transition-opacity p-1.5 rounded-md hover:bg-red-50 dark:hover:bg-red-900/20 text-gray-400 hover:text-red-500"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </motion.div>
                  ))}
                </AnimatePresence>
              </div>
            ) : (
              <div className="h-32 flex items-center justify-center text-sm text-gray-400">
                No meals logged today
              </div>
            )}
          </CardContent>
        </Card>
      </motion.div>
    </div>
  );
}
