export function searchFoods(query: string): FoodItem[] {
  const q = query.toLowerCase();
  return HK_FOOD_DATABASE.filter(
    (f) => f.name.toLowerCase().includes(q) || f.category.toLowerCase().includes(q)
  );
}

export function getFoodsByCategory(category: string): FoodItem[] {
  return HK_FOOD_DATABASE.filter((f) => f.category === category);
}

export function findAlternatives(foodName: string): FoodItem[] {
  const food = HK_FOOD_DATABASE.find((f) => f.name === foodName);
  if (!food) return [];
  return HK_FOOD_DATABASE.filter(
    (f) => f.category === food.category && f.name !== food.name
  ).slice(0, 5);
}

export function getQuickPrepMeals(): FoodItem[] {
  return HK_FOOD_DATABASE.filter((f) => f.isQuickPrep);
}

export function getHealthyOptions(): FoodItem[] {
  return HK_FOOD_DATABASE.filter((f) => f.protein > 5 && f.calories < 200);
}

export const FOOD_CATEGORIES = [...new Set(HK_FOOD_DATABASE.map((f) => f.category))];
