const ageFromDOB = (dob: string): number => {
  const birth = new Date(dob);
  const now = new Date();
  let age = now.getFullYear() - birth.getFullYear();
  const m = now.getMonth() - birth.getMonth();
  if (m < 0 || (m === 0 && now.getDate() < birth.getDate())) age--;
  return age;
};

const syncClientToNutrition = (
  client: Client,
  setBodyStats: NutritionState['setBodyStats']
) => {
  const updates: Partial<{ age: number; weight: number; height: number; bodyFat: number | null; gender: 'male' | 'female' }> = {};

  if (client.dateOfBirth) {
    const age = ageFromDOB(client.dateOfBirth);
    if (age > 0) updates.age = age;
  }
  if (client.height && client.height > 0) {
    updates.height = Math.round(client.height);
  }
  if (client.gender === 'male' || client.gender === 'female') {
    updates.gender = client.gender;
  }

  // Use latest bioPrint for weight & body fat
  const bioPrints = client.bioPrints ?? [];
  if (bioPrints.length > 0) {
    const latest = bioPrints[bioPrints.length - 1];
    if (latest.weight > 0) updates.weight = latest.weight;
    if (latest.bodyFat && latest.bodyFat > 0) updates.bodyFat = latest.bodyFat;
  }

  if (Object.keys(updates).length > 0) {
    setBodyStats(updates);
  }
};

