  const { selectedClient } = useClientStore();

  // Local unit toggles
  const [weightUnit, setWeightUnit] = useState<'kg' | 'lb'>('kg');
  const [heightUnit, setHeightUnit] = useState<'cm' | 'ft'>('cm');

  // Run TDEE calc on mount if not already computed
