    (field: string, value: string) => {
      const num = parseFloat(value);
      if (value === '' || isNaN(num)) {
        store.setBodyStats({ [field]: field === 'bodyFat' ? null : 0 });
        return;
      }
      store.setBodyStats({ [field]: field === 'bodyFat' ? num : num });
    },
    [store]
