/*  Constants & Helpers                                                */
/* ------------------------------------------------------------------ */

const easeSpring = [0.34, 1.56, 0.64, 1] as [number, number, number, number];

const CATEGORY_COLORS: Record<Achievement['category'], { header: string; badge: string; border: string; bg: string }> = {
  streak: { header: 'text-[#00AEEF]', badge: 'bg-[#00AEEF]/10 text-[#00AEEF]', border: 'border-[#00AEEF]/20', bg: 'bg-[#00AEEF]/5' },
  macro: { header: 'text-emerald-500', badge: 'bg-emerald-500/10 text-emerald-500', border: 'border-emerald-500/20', bg: 'bg-emerald-500/5' },
  logging: { header: 'text-amber-500', badge: 'bg-amber-500/10 text-amber-500', border: 'border-amber-500/20', bg: 'bg-amber-500/5' },
  'meal-plan': { header: 'text-purple-500', badge: 'bg-purple-500/10 text-purple-500', border: 'border-purple-500/20', bg: 'bg-purple-500/5' },
  milestone: { header: 'text-pink-500', badge: 'bg-pink-500/10 text-pink-500', border: 'border-pink-500/20', bg: 'bg-pink-500/5' },
};

const CATEGORY_LABELS: Record<Achievement['category'], string> = {
  streak: 'Streaks',
  macro: 'Macro Mastery',
  logging: 'Logging',
  'meal-plan': 'Meal Planning',
  milestone: 'Milestones',
};

const ICON_MAP: Record<string, React.ComponentType<{ className?: string }>> = {
  FileCheck,
  Flame,
  Target,
  Droplets,
  CalendarCheck,
  Apple,
  Trophy,
  Beef,
  Utensils,
  Salad,
  Droplet,
  Award,
  Star,
  Zap,
  TrendingUp,
};

/* ------------------------------------------------------------------ */
/*  Demo Data                                                          */
/* ------------------------------------------------------------------ */

