const generateId = () => Math.random().toString(36).substring(2, 9);

const getWeekStart = () => {
  const d = new Date();
  const day = d.getDay();
  const diff = d.getDate() - day + (day === 0 ? -6 : 1);
  return new Date(d.setDate(diff)).toISOString().split('T')[0];
};

function createEmptyDay(day: string): DayPlan {
  return {
    day,
    meals: [],
    macroTotals: { protein: 0, carbs: 0, fats: 0, calories: 0 },
  };
}

function createEmptyPlan(): WeeklyPlan {
  return {
    weekStart: getWeekStart(),
    days: DAYS.map((d) => createEmptyDay(d)),
  };
}

function foodToPlannedMeal(food: FoodItem, mealType: MealType): PlannedMeal {
  return {
    id: generateId(),
    mealType,
    name: food.name,
    calories: food.calories,
    protein: food.protein,
    carbs: food.carbs,
    fats: food.fats,
    prepTime: food.isQuickPrep ? 10 : 30,
    isQuickPrep: food.isQuickPrep,
    recipeUrl: undefined,
  };
}

function recalcDay(day: DayPlan): DayPlan {
  const totals = day.meals.reduce(
    (acc, m) => ({
      protein: acc.protein + m.protein,
      carbs: acc.carbs + m.carbs,
      fats: acc.fats + m.fats,
      calories: acc.calories + m.calories,
    }),
    { protein: 0, carbs: 0, fats: 0, calories: 0 }
  );
  return { ...day, macroTotals: totals };
}

