/** Mini donut chart for macro breakdown */
function MiniDonut({
  protein,
  carbs,
  fats,
  size = 48,
}: {
  protein: number;
  carbs: number;
  fats: number;
  size?: number;
}) {
  const total = protein + carbs + fats;
  if (total === 0) {
    return (
      <svg width={size} height={size} viewBox="0 0 48 48">
        <circle cx="24" cy="24" r="18" fill="none" stroke="currentColor" strokeWidth="6" className="text-gray-200 dark:text-gray-700" />
      </svg>
    );
  }
  const r = 18;
  const circ = 2 * Math.PI * r;
  const p1 = (protein / total) * circ;
  const p2 = (carbs / total) * circ;
  const offset2 = -p1;
  const offset3 = -(p1 + p2);

  return (
    <svg width={size} height={size} viewBox="0 0 48 48" className="-rotate-90">
      <circle cx="24" cy="24" r={r} fill="none" stroke="#00AEEF" strokeWidth="6" strokeDasharray={`${p1} ${circ - p1}`} />
      <circle
        cx="24"
        cy="24"
        r={r}
        fill="none"
        stroke="#F59E0B"
        strokeWidth="6"
        strokeDasharray={`${p2} ${circ - p2}`}
        strokeDashoffset={offset2}
      />
      <circle
        cx="24"
        cy="24"
        r={r}
        fill="none"
        stroke="#EAB308"
        strokeWidth="6"
        strokeDasharray={`${circ - p1 - p2} ${p1 + p2}`}
        strokeDashoffset={offset3}
      />
    </svg>
  );
}

/** A meal card shown in the weekly grid cell */
function MealCard({
  meal,
  onRemove,
  onSwap,
  onDuplicate,
}: {
  meal: PlannedMeal;
  onRemove: () => void;
  onSwap: () => void;
  onDuplicate: () => void;
}) {
  const macroTotal = meal.protein + meal.carbs + meal.fats;
  return (
    <div className="group/card h-full flex flex-col justify-between">
      <div>
        <div className="flex items-start justify-between gap-1 mb-1">
          <span className="text-[11px] font-medium text-gray-900 dark:text-white leading-tight line-clamp-2 flex-1">
            {meal.name}
          </span>
          <button
            onClick={(e) => { e.stopPropagation(); onRemove(); }}
            className="opacity-0 group-hover/card:opacity-100 transition-opacity text-gray-400 hover:text-red-500"
          >
            <X className="w-3 h-3" />
          </button>
        </div>
        <div className="flex items-center gap-1 mb-1.5">
          <Badge variant="outline" className="text-[9px] px-1 py-0 h-auto border-gray-200 dark:border-white/10 text-gray-500">
            {meal.calories} kcal
          </Badge>
          {meal.isQuickPrep && (
            <Badge variant="outline" className="text-[9px] px-1 py-0 h-auto border-emerald-200 dark:border-emerald-500/30 text-emerald-600 dark:text-emerald-400">
              <Zap className="w-2.5 h-2.5 mr-0.5 inline" />
              {meal.prepTime}m
            </Badge>
          )}
        </div>
        {/* Macro mini bars */}
        <div className="flex h-1 rounded-full overflow-hidden bg-gray-100 dark:bg-white/5">
          {macroTotal > 0 && (
            <>
              <div className="bg-[#00AEEF]" style={{ width: `${(meal.protein / macroTotal) * 100}%` }} />
              <div className="bg-amber-500" style={{ width: `${(meal.carbs / macroTotal) * 100}%` }} />
              <div className="bg-yellow-500" style={{ width: `${(meal.fats / macroTotal) * 100}%` }} />
            </>
          )}
        </div>
      </div>
      {/* Quick actions - visible on hover */}
      <div className="flex items-center gap-1 mt-1.5 opacity-0 group-hover/card:opacity-100 transition-opacity">
        <button onClick={(e) => { e.stopPropagation(); onSwap(); }} className="text-[10px] text-[#00AEEF] hover:underline">
          Swap
        </button>
        <span className="text-gray-300 dark:text-gray-700">·</span>
        <button onClick={(e) => { e.stopPropagation(); onDuplicate(); }} className="text-[10px] text-[#00AEEF] hover:underline">
          Copy
        </button>
      </div>
    </div>
  );
}

/** A food card shown in the picker dialog */
function FoodCard({ food, onClick }: { food: FoodItem; onClick: () => void }) {
  return (
    <button
      onClick={onClick}
      className="w-full text-left p-3 rounded-xl border border-gray-100 dark:border-white/5 bg-gray-50/50 dark:bg-white/[0.02] hover:bg-gray-100 dark:hover:bg-white/5 hover:border-gray-200 dark:hover:border-white/10 transition-all group"
    >
      <div className="flex items-start justify-between gap-2 mb-1">
        <div className="flex items-center gap-1.5 min-w-0">
          <span className="text-sm font-medium text-gray-900 dark:text-white truncate">{food.name}</span>
          {food.localName && (
            <span className="text-[10px] text-gray-400 dark:text-gray-600 shrink-0">{food.localName}</span>
          )}
        </div>
        <span className="text-xs font-bold text-gray-900 dark:text-white shrink-0">{food.calories}</span>
      </div>
      <div className="flex items-center gap-1.5 flex-wrap mb-1.5">
        <Badge
          variant="outline"
          className={cn('text-[9px] px-1 py-0 h-auto border', CUISINE_COLORS[food.cuisine])}
        >
          {CUISINE_LABELS[food.cuisine]}
        </Badge>
        <span className="text-[10px] text-gray-500 dark:text-gray-500 capitalize">{food.category}</span>
        {food.isQuickPrep && (
          <Badge variant="outline" className="text-[9px] px-1 py-0 h-auto border-emerald-200 dark:border-emerald-500/30 text-emerald-600 dark:text-emerald-400">
            <Clock className="w-2.5 h-2.5 mr-0.5 inline" />
            Quick
          </Badge>
        )}
        {food.isHealthyOption && (
          <Badge variant="outline" className="text-[9px] px-1 py-0 h-auto border-emerald-200 dark:border-emerald-500/30 text-emerald-600 dark:text-emerald-400">
            <Leaf className="w-2.5 h-2.5 mr-0.5 inline" />
            Healthy
          </Badge>
        )}
      </div>
      <div className="flex items-center gap-2 text-[10px] text-gray-500 dark:text-gray-500">
        <span>P: {food.protein}g</span>
        <span>C: {food.carbs}g</span>
        <span>F: {food.fats}g</span>
        <span className="text-gray-300 dark:text-gray-700">|</span>
        <span>{food.servingSize}</span>
      </div>
    </button>
  );
}
