/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

type DateRange = '7' | '30' | '90' | 'all';

interface CombinedDailyData {
  date: string;
  tdee: number;
  bmr: number;
  weight: number | null;
  caloriesConsumed: number;
  protein: number;
  carbs: number;
  fats: number;
  compliance: number | null;
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

const generateId = () => Math.random().toString(36).substring(2, 9);

const formatDate = (d: Date) => d.toISOString().split('T')[0];

const formatShortDate = (dateStr: string) => {
  const d = new Date(dateStr + 'T00:00:00');
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
};

const easeSpring = [0.34, 1.56, 0.64, 1] as [number, number, number, number];

/** Generate 30 days of realistic metabolic demo data */
function generateDemoData(): { tdeeHistory: TDEEEntry[]; dailyLogs: DailyLog[] } {
  const tdeeHistory: TDEEEntry[] = [];
  const dailyLogs: DailyLog[] = [];

  const baseWeight = 75;
  const baseTDEE = 2200;
  const baseBMR = 1650;

  const sampleMeals = [
    { name: 'Oatmeal & Banana', calories: 350, protein: 12, carbs: 58, fats: 6, fiber: 8 },
    { name: 'Chicken Rice', calories: 550, protein: 35, carbs: 68, fats: 14, fiber: 3 },
    { name: 'Salmon & Vegetables', calories: 480, protein: 38, carbs: 22, fats: 26, fiber: 6 },
    { name: 'Greek Yogurt', calories: 150, protein: 15, carbs: 8, fats: 8, fiber: 0 },
    { name: 'Protein Shake', calories: 180, protein: 30, carbs: 5, fats: 4, fiber: 1 },
    { name: 'Avocado Toast', calories: 320, protein: 10, carbs: 30, fats: 18, fiber: 7 },
    { name: 'Grilled Chicken Salad', calories: 420, protein: 42, carbs: 18, fats: 20, fiber: 5 },
    { name: 'Rice & Vegetables', calories: 380, protein: 10, carbs: 62, fats: 10, fiber: 8 },
    { name: 'Eggs & Toast', calories: 300, protein: 18, carbs: 24, fats: 16, fiber: 2 },
    { name: 'Steak & Potatoes', calories: 650, protein: 48, carbs: 35, fats: 36, fiber: 4 },
    { name: 'Fruit Smoothie', calories: 220, protein: 6, carbs: 45, fats: 3, fiber: 5 },
    { name: 'Tuna Sandwich', calories: 400, protein: 28, carbs: 38, fats: 14, fiber: 4 },
  ];

  for (let i = 29; i >= 0; i--) {
    const date = new Date();
    date.setDate(date.getDate() - i);
    const dateStr = formatDate(date);

    // Gradual weight decrease with fluctuation
    const dayProgress = (29 - i) / 29;
    const fluctuation = Math.sin(i * 0.8) * 0.3 + Math.random() * 0.2 - 0.1;
    const weight = Math.round((baseWeight - dayProgress * 1.5 + fluctuation) * 10) / 10;

    // TDEE and BMR tracking weight
    const weightFactor = weight / baseWeight;
    const tdee = Math.round(baseTDEE * weightFactor + (Math.random() * 80 - 40));
    const bmr = Math.round(baseBMR * weightFactor + (Math.random() * 40 - 20));

    const bodyStats = {
      age: 28,
      weight,
      height: 175,
      bodyFat: 18 - dayProgress * 1.2,
      gender: 'male' as const,
      activityLevel: 'moderate' as const,
    };

    tdeeHistory.push({
      date: dateStr,
      bmr,
      tdee,
      method: 'mifflin',
      bodyStats,
    });

    // Generate daily meals
    const numMeals = 3 + (Math.random() > 0.3 ? 1 : 0);
    const dailyMeals = [];
    const usedIndices = new Set<number>();
    for (let m = 0; m < numMeals; m++) {
      let idx = Math.floor(Math.random() * sampleMeals.length);
      while (usedIndices.has(idx)) idx = Math.floor(Math.random() * sampleMeals.length);
      usedIndices.add(idx);
      const meal = sampleMeals[idx];
      dailyMeals.push({
        id: generateId(),
        name: meal.name,
        mealType: (['breakfast', 'lunch', 'dinner', 'snack'] as const)[m],
        calories: meal.calories,
        protein: meal.protein,
        carbs: meal.carbs,
        fats: meal.fats,
        fiber: meal.fiber,
        timestamp: `${dateStr}T${8 + m * 4}:00:00`,
        servings: 1,
      });
    }

    dailyLogs.push({
      date: dateStr,
      meals: dailyMeals,
      waterIntake: 6 + Math.floor(Math.random() * 4),
      weight,
    });
  }

  return { tdeeHistory, dailyLogs };
}

/** Combine TDEE + daily log data by date */
function combineData(tdeeHistory: TDEEEntry[], dailyLogs: DailyLog[]): CombinedDailyData[] {
  const tdeeMap = new Map(tdeeHistory.map((e) => [e.date, e]));
  const logMap = new Map(dailyLogs.map((l) => [l.date, l]));

  const allDates = Array.from(new Set([...tdeeMap.keys(), ...logMap.keys()])).sort();

  const targets = { protein: 150, carbs: 250, fats: 65 };

  return allDates.map((date) => {
    const tdee = tdeeMap.get(date);
    const log = logMap.get(date);
    const totals = log
      ? {
          calories: log.meals.reduce((s, m) => s + m.calories, 0),
          protein: log.meals.reduce((s, m) => s + m.protein, 0),
          carbs: log.meals.reduce((s, m) => s + m.carbs, 0),
          fats: log.meals.reduce((s, m) => s + m.fats, 0),
        }
      : { calories: 0, protein: 0, carbs: 0, fats: 0 };

    const proteinPct = Math.min(100, Math.round((totals.protein / targets.protein) * 100));
    const carbsPct = Math.min(100, Math.round((totals.carbs / targets.carbs) * 100));
    const fatsPct = Math.min(100, Math.round((totals.fats / targets.fats) * 100));
    const compliance = Math.round((proteinPct + carbsPct + fatsPct) / 3);

    return {
      date,
      tdee: tdee?.tdee ?? 0,
      bmr: tdee?.bmr ?? 0,
      weight: log?.weight ?? null,
      caloriesConsumed: totals.calories,
      protein: proteinPct,
      carbs: carbsPct,
      fats: fatsPct,
      compliance: log ? compliance : null,
    };
  });
}

/* ------------------------------------------------------------------ */
/*  Component                                                          */
/* ------------------------------------------------------------------ */

