/* ─── Fallback ingredient generator for foods not in map ─── */
function generateFallbackIngredients(meal: PlannedMeal): Omit<ShoppingItem, 'id' | 'checked' | 'atHome' | 'sourceMeals'>[] {
  const name = meal.name.toLowerCase();
  const items: Omit<ShoppingItem, 'id' | 'checked' | 'atHome' | 'sourceMeals'>[] = [];

  if (name.includes('chicken')) {
    items.push({ name: 'Chicken Breast / Thigh', category: 'protein', quantity: 200, unit: 'g', estimatedPricePerUnit: 5 });
  }
  if (name.includes('salmon') || name.includes('fish')) {
    items.push({ name: 'Fish Fillet', category: 'protein', quantity: 200, unit: 'g', estimatedPricePerUnit: 12 });
  }
  if (name.includes('beef') || name.includes('steak')) {
    items.push({ name: 'Beef Steak', category: 'protein', quantity: 200, unit: 'g', estimatedPricePerUnit: 15 });
  }
  if (name.includes('pork')) {
    items.push({ name: 'Pork', category: 'protein', quantity: 200, unit: 'g', estimatedPricePerUnit: 8 });
  }
  if (name.includes('prawn') || name.includes('shrimp')) {
    items.push({ name: 'Prawns', category: 'protein', quantity: 200, unit: 'g', estimatedPricePerUnit: 12 });
  }
  if (name.includes('tofu')) {
    items.push({ name: 'Tofu', category: 'protein', quantity: 300, unit: 'g', estimatedPricePerUnit: 2.5 });
  }
  if (name.includes('egg')) {
    items.push({ name: 'Egg', category: 'dairy', quantity: 3, unit: 'pieces', estimatedPricePerUnit: 0.5 });
  }
  if (name.includes('rice')) {
    items.push({ name: 'Jasmine Rice', category: 'grains', quantity: 200, unit: 'g', estimatedPricePerUnit: 3 });
  }
  if (name.includes('noodle') || name.includes('mee') || name.includes('kway')) {
    items.push({ name: 'Noodles', category: 'grains', quantity: 200, unit: 'g', estimatedPricePerUnit: 3 });
  }
  if (name.includes('bread') || name.includes('toast')) {
    items.push({ name: 'Bread', category: 'grains', quantity: 4, unit: 'slices', estimatedPricePerUnit: 3 });
  }
  if (name.includes('pasta')) {
    items.push({ name: 'Pasta', category: 'grains', quantity: 150, unit: 'g', estimatedPricePerUnit: 3 });
  }
  if (name.includes('salad')) {
    items.push({ name: 'Mixed Salad Greens', category: 'produce', quantity: 150, unit: 'g', estimatedPricePerUnit: 4 });
  }
  if (name.includes('oats') || name.includes('congee')) {
    items.push({ name: 'Oats / Rice (for congee)', category: 'grains', quantity: 100, unit: 'g', estimatedPricePerUnit: 3 });
  }
  if (name.includes('sushi') || name.includes('bento')) {
    items.push({ name: 'Sushi Rice', category: 'grains', quantity: 200, unit: 'g', estimatedPricePerUnit: 4 });
    items.push({ name: 'Nori Sheets', category: 'pantry', quantity: 3, unit: 'sheets', estimatedPricePerUnit: 4 });
  }
  if (name.includes('soup')) {
    items.push({ name: 'Soup Stock', category: 'pantry', quantity: 500, unit: 'ml', estimatedPricePerUnit: 2 });
  }
  if (name.includes('curry')) {
    items.push({ name: 'Curry Paste / Powder', category: 'sauces', quantity: 30, unit: 'g', estimatedPricePerUnit: 4 });
    items.push({ name: 'Coconut Milk', category: 'pantry', quantity: 200, unit: 'ml', estimatedPricePerUnit: 3.5 });
  }
  if (name.includes('kimchi')) {
    items.push({ name: 'Kimchi', category: 'produce', quantity: 200, unit: 'g', estimatedPricePerUnit: 6 });
  }
  if (name.includes('smoothie') || name.includes('bowl')) {
    items.push({ name: 'Mixed Frozen Fruits', category: 'frozen', quantity: 200, unit: 'g', estimatedPricePerUnit: 6 });
    items.push({ name: 'Greek Yogurt', category: 'dairy', quantity: 150, unit: 'g', estimatedPricePerUnit: 5 });
  }
  if (name.includes('protein shake') || name.includes('whey')) {
    items.push({ name: 'Protein Powder', category: 'pantry', quantity: 1, unit: 'scoop', estimatedPricePerUnit: 3 });
  }
  if (name.includes('avocado')) {
    items.push({ name: 'Avocado', category: 'produce', quantity: 1, unit: 'piece', estimatedPricePerUnit: 3 });
  }

  /* Generic catch-all for meals with no matched ingredients */
  if (items.length === 0) {
    items.push({ name: `${meal.name} (main ingredient)`, category: 'protein', quantity: 200, unit: 'g', estimatedPricePerUnit: 8 });
    items.push({ name: 'Mixed Vegetables', category: 'produce', quantity: 150, unit: 'g', estimatedPricePerUnit: 3 });
    items.push({ name: 'Cooking Oil', category: 'pantry', quantity: 15, unit: 'ml', estimatedPricePerUnit: 3 });
  }

  return items;
}

/* ================================================================
   Component: ShoppingListPage
   ================================================================ */

export default function ShoppingListPage() {
  const [shoppingItems, setShoppingItems] = useState<ShoppingItem[]>([]);
  const [hasPlan, setHasPlan] = useState(false);
  const [expandedCategories, setExpandedCategories] = useState<Set<ShoppingCategory>>(
    new Set(CATEGORIES)
  );
  const [pantryItems, setPantryItems] = useState<PantryItem[]>([]);
  const [showPantry, setShowPantry] = useState(false);
  const [newPantryName, setNewPantryName] = useState('');
  const [newPantryCategory, setNewPantryCategory] = useState<ShoppingCategory>('pantry');

  /* ── Load pantry from localStorage ── */
  useEffect(() => {
    try {
      const raw = localStorage.getItem('azfit-pantry-items');
      if (raw) setPantryItems(JSON.parse(raw));
    } catch { /* ignore */ }
  }, []);

  const persistPantry = useCallback((items: PantryItem[]) => {
    setPantryItems(items);
    localStorage.setItem('azfit-pantry-items', JSON.stringify(items));
  }, []);

  /* ── Generate shopping list from meal plan ── */
  const generateFromMealPlan = useCallback(() => {
    try {
      const raw = localStorage.getItem('azfit-meal-plan');
      let weeklyPlan: WeeklyPlan | null = null;
      if (raw) {
        weeklyPlan = JSON.parse(raw) as WeeklyPlan;
      }

      if (!weeklyPlan) {
        setHasPlan(false);
        return;
      }

      const itemMap = new Map<string, ShoppingItem>();
      const pantryNames = new Set(pantryItems.map((p) => p.name.toLowerCase()));

      for (const day of weeklyPlan.days) {
        for (const meal of day.meals) {
          const mapped = INGREDIENT_MAP[meal.name];
          const ingredients = mapped
            ? mapped.items
            : generateFallbackIngredients(meal);

          for (const ing of ingredients) {
            const key = `${ing.name}-${ing.category}`;
            if (itemMap.has(key)) {
              const existing = itemMap.get(key)!;
              existing.quantity += ing.quantity;
              if (!existing.sourceMeals.includes(meal.name)) {
                existing.sourceMeals.push(meal.name);
              }
            } else {
              itemMap.set(key, {
                id: Math.random().toString(36).substring(2, 9),
                name: ing.name,
                category: ing.category,
                quantity: ing.quantity,
                unit: ing.unit,
                estimatedPricePerUnit: ing.estimatedPricePerUnit,
                checked: false,
                atHome: pantryNames.has(ing.name.toLowerCase()),
                sourceMeals: [meal.name],
              });
            }
          }
        }
      }

      setShoppingItems(Array.from(itemMap.values()));
      setHasPlan(true);
    } catch {
      setHasPlan(false);
    }
  }, [pantryItems]);

  /* ── Toggle item checked ── */
  const toggleChecked = useCallback((id: string) => {
    setShoppingItems((prev) =>
      prev.map((item) => (item.id === id ? { ...item, checked: !item.checked } : item))
    );
  }, []);

  /* ── Toggle at-home ── */
  const toggleAtHome = useCallback((id: string) => {
    setShoppingItems((prev) =>
      prev.map((item) => (item.id === id ? { ...item, atHome: !item.atHome } : item))
    );
  }, []);

  /* ── Adjust quantity ── */
  const adjustQuantity = useCallback((id: string, delta: number) => {
    setShoppingItems((prev) =>
      prev.map((item) =>
        item.id === id
          ? { ...item, quantity: Math.max(0, item.quantity + delta) }
          : item
      )
    );
  }, []);

  /* ── Toggle category expanded ── */
  const toggleCategory = useCallback((cat: ShoppingCategory) => {
    setExpandedCategories((prev) => {
      const next = new Set(prev);
      if (next.has(cat)) next.delete(cat);
      else next.add(cat);
      return next;
    });
  }, []);

  /* ── Add pantry item ── */
  const addPantryItem = useCallback(() => {
    if (!newPantryName.trim()) return;
    const newItem: PantryItem = {
      id: Math.random().toString(36).substring(2, 9),
      name: newPantryName.trim(),
      category: newPantryCategory,
    };
    persistPantry([...pantryItems, newItem]);
    setNewPantryName('');
  }, [newPantryName, newPantryCategory, pantryItems, persistPantry]);

  const removePantryItem = useCallback(
    (id: string) => {
      persistPantry(pantryItems.filter((p) => p.id !== id));
    },
    [pantryItems, persistPantry]
  );

  /* ── Copy to clipboard ── */
  const copyToClipboard = useCallback(() => {
    const activeItems = shoppingItems.filter((i) => !i.atHome);
    const lines: string[] = ['🛒 Shopping List\n'];
    for (const cat of CATEGORIES) {
      const catItems = activeItems.filter((i) => i.category === cat);
      if (catItems.length === 0) continue;
      lines.push(`${CATEGORY_CONFIG[cat].label}:`);
      for (const item of catItems) {
        const check = item.checked ? '✓' : '☐';
        lines.push(`  ${check} ${item.name} — ${item.quantity} ${item.unit}`);
      }
      lines.push('');
    }
    const total = activeItems.reduce((a, i) => a + i.estimatedPricePerUnit * (i.quantity > 100 ? i.quantity / 1000 : i.quantity), 0);
    lines.push(`Estimated Total: HKD ${total.toFixed(2)}`);
    navigator.clipboard.writeText(lines.join('\n'));
  }, [shoppingItems]);

  /* ── Print ── */
  const printList = useCallback(() => {
    window.print();
  }, []);

  /* ── Computed grouped items ── */
  const groupedItems = useMemo(() => {
    const grouped: Record<ShoppingCategory, ShoppingItem[]> = {
      produce: [],
      protein: [],
      dairy: [],
      grains: [],
      sauces: [],
      beverages: [],
      frozen: [],
      pantry: [],
    };
    for (const item of shoppingItems) {
      if (item.quantity > 0) {
        grouped[item.category].push(item);
      }
    }
    return grouped;
  }, [shoppingItems]);

  /* ── Estimated total price ── */
  const totalPrice = useMemo(() => {
    return shoppingItems
      .filter((i) => !i.atHome && !i.checked)
      .reduce((sum, item) => {
        const qty = item.unit.includes('g') && item.quantity > 100
          ? item.quantity / 1000
          : item.unit.includes('ml') && item.quantity > 100
            ? item.quantity / 1000
            : item.quantity;
        return sum + item.estimatedPricePerUnit * qty;
      }, 0);
  }, [shoppingItems]);

  /* ── Stats ── */
  const stats = useMemo(() => {
    const total = shoppingItems.length;
    const checked = shoppingItems.filter((i) => i.checked).length;
    const atHome = shoppingItems.filter((i) => i.atHome).length;
    return { total, checked, atHome, remaining: total - checked - atHome };
  }, [shoppingItems]);

  /* ═══════════════════════════════════════════════════════════
     Render
     ═══════════════════════════════════════════════════════════ */

  if (!hasPlan) {
    return (
      <div className="max-w-4xl mx-auto px-4 sm:px-6 py-12 min-h-[100dvh]">
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] as [number, number, number, number] }}
        >
          <div className="flex items-center gap-3 mb-8">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-sky-500 to-sky-600 flex items-center justify-center shadow-lg shadow-sky-500/25">
              <ShoppingCart className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Shopping List</h1>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                Auto-generated from your weekly meal plan.
              </p>
            </div>
          </div>

          <Card className="border-gray-200 dark:border-white/5 bg-white dark:bg-[#141414]">
            <CardContent className="flex flex-col items-center justify-center py-16 px-6 text-center">
              <div className="w-20 h-20 rounded-2xl bg-gray-100 dark:bg-white/5 flex items-center justify-center mb-4">
                <ShoppingBag className="w-10 h-10 text-gray-300 dark:text-gray-600" />
              </div>
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">
                No Meal Plan Found
              </h3>
              <p className="text-sm text-gray-500 dark:text-gray-400 max-w-sm mb-6">
                Create a meal plan in the Meal Planner first to generate your shopping list. Your list will be automatically organized by store section.
              </p>
              <Button
                onClick={generateFromMealPlan}
                className="gap-2 bg-gradient-to-r from-[#00AEEF] to-[#33BFF2] text-white hover:opacity-90"
              >
                <Sparkles className="w-4 h-4" />
                Generate from Meal Plan
              </Button>
            </CardContent>
          </Card>
        </motion.div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 py-8 min-h-[100dvh]">
      {/* Header */}
      <motion.div
        initial={{ opacity: 0, y: 16 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] as [number, number, number, number] }}
        className="mb-6"
      >
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-sky-500 to-sky-600 flex items-center justify-center shadow-lg shadow-sky-500/25">
              <ShoppingCart className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Shopping List</h1>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                {stats.remaining} items remaining · HKD {totalPrice.toFixed(2)} est.
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2 flex-wrap">
            <Button variant="outline" size="sm" onClick={generateFromMealPlan} className="gap-1.5">
              <RotateCcw className="w-4 h-4" />
              Regenerate
            </Button>
            <Button variant="outline" size="sm" onClick={copyToClipboard} className="gap-1.5">
              <Copy className="w-4 h-4" />
              Copy
            </Button>
            <Button variant="outline" size="sm" onClick={printList} className="gap-1.5">
              <Printer className="w-4 h-4" />
              Print
            </Button>
          </div>
        </div>
      </motion.div>

      {/* Stats Bar */}
      <motion.div
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.1, duration: 0.4, ease: [0.16, 1, 0.3, 1] as [number, number, number, number] }}
        className="grid grid-cols-4 gap-3 mb-6"
      >
        {[
          { label: 'Total', value: stats.total, icon: ShoppingCart, color: 'text-sky-600 bg-sky-50 dark:text-sky-400 dark:bg-sky-950/30' },
          { label: 'Checked', value: stats.checked, icon: Check, color: 'text-emerald-600 bg-emerald-50 dark:text-emerald-400 dark:bg-emerald-950/30' },
          { label: 'At Home', value: stats.atHome, icon: Home, color: 'text-gray-600 bg-gray-100 dark:text-gray-400 dark:bg-gray-800/30' },
          { label: 'Remaining', value: stats.remaining, icon: Package, color: 'text-amber-600 bg-amber-50 dark:text-amber-400 dark:bg-amber-950/30' },
        ].map((s) => (
          <Card key={s.label} className="border-gray-200 dark:border-white/5 bg-white dark:bg-[#141414]">
            <CardContent className="p-3 flex items-center gap-2">
              <div className={cn('w-8 h-8 rounded-lg flex items-center justify-center', s.color)}>
                <s.icon className="w-4 h-4" />
              </div>
              <div>
                <div className="text-lg font-bold text-gray-900 dark:text-white leading-none">{s.value}</div>
                <div className="text-[10px] text-gray-500 dark:text-gray-400">{s.label}</div>
              </div>
            </CardContent>
          </Card>
        ))}
      </motion.div>

      {/* Price Total Card */}
      <motion.div
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.15, duration: 0.4, ease: [0.16, 1, 0.3, 1] as [number, number, number, number] }}
        className="mb-6"
      >
        <Card className="border-gray-200 dark:border-white/5 bg-gradient-to-r from-emerald-50 to-sky-50 dark:from-emerald-950/20 dark:to-sky-950/20">
          <CardContent className="p-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-white/80 dark:bg-white/10 flex items-center justify-center">
                <span className="text-lg font-bold text-emerald-600 dark:text-emerald-400">$</span>
              </div>
              <div>
                <div className="text-xs text-gray-600 dark:text-gray-400">Estimated Total</div>
                <div className="text-2xl font-bold text-gray-900 dark:text-white">
                  HKD {totalPrice.toFixed(2)}
                </div>
              </div>
            </div>
            <div className="text-xs text-gray-500 dark:text-gray-400 text-right">
              Based on current<br />market prices
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Category Sections */}
      <motion.div
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.2, duration: 0.4, ease: [0.16, 1, 0.3, 1] as [number, number, number, number] }}
        className="space-y-3"
      >
        {CATEGORIES.map((cat) => {
          const items = groupedItems[cat];
          if (items.length === 0) return null;
          const isExpanded = expandedCategories.has(cat);
          const config = CATEGORY_CONFIG[cat];
          const CatIcon = config.icon;
          const checkedCount = items.filter((i) => i.checked).length;

          return (
            <Card key={cat} className="border-gray-200 dark:border-white/5 bg-white dark:bg-[#141414] overflow-hidden">
              <button
                onClick={() => toggleCategory(cat)}
                className="w-full flex items-center justify-between p-4 hover:bg-gray-50 dark:hover:bg-white/[0.02] transition-colors"
              >
                <div className="flex items-center gap-3">
                  <div className={cn('w-9 h-9 rounded-lg flex items-center justify-center border', config.color, config.darkColor)}>
                    <CatIcon className="w-4 h-4" />
                  </div>
                  <div className="text-left">
                    <span className="text-sm font-semibold text-gray-900 dark:text-white">{config.label}</span>
                    <span className="text-xs text-gray-500 dark:text-gray-400 ml-2">
                      {checkedCount}/{items.length} done
                    </span>
                  </div>
                </div>
                {isExpanded ? (
                  <ChevronUp className="w-4 h-4 text-gray-400" />
                ) : (
                  <ChevronDown className="w-4 h-4 text-gray-400" />
                )}
              </button>
              <AnimatePresence>
                {isExpanded && (
                  <motion.div
                    initial={{ height: 0 }}
                    animate={{ height: 'auto' }}
                    exit={{ height: 0 }}
                    transition={{ duration: 0.25, ease: [0.16, 1, 0.3, 1] as [number, number, number, number] }}
                    className="overflow-hidden"
                  >
                    <Separator className="bg-gray-100 dark:bg-white/5" />
                    <div className="divide-y divide-gray-100 dark:divide-white/5">
                      {items.map((item) => (
                        <div
                          key={item.id}
                          className={cn(
                            'flex items-center gap-3 px-4 py-3 transition-colors',
                            item.atHome && 'opacity-40 bg-gray-50 dark:bg-white/[0.02]'
                          )}
                        >
                          <Checkbox
                            checked={item.checked}
                            onCheckedChange={() => toggleChecked(item.id)}
                            className="shrink-0"
                          />
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-1.5">
                              <span
                                className={cn(
                                  'text-sm',
                                  item.checked
                                    ? 'line-through text-gray-400 dark:text-gray-600'
                                    : 'text-gray-900 dark:text-white'
                                )}
                              >
                                {item.name}
                              </span>
                              {item.sourceMeals.length > 0 && (
                                <Badge variant="outline" className="text-[9px] px-1 py-0 h-auto border-gray-200 dark:border-white/10 text-gray-400 shrink-0">
                                  {item.sourceMeals.length} meal{item.sourceMeals.length > 1 ? 's' : ''}
                                </Badge>
                              )}
                            </div>
                            <div className="text-[11px] text-gray-500 dark:text-gray-500">
                              Est. HKD {item.estimatedPricePerUnit.toFixed(2)} / {item.unit}
                            </div>
                          </div>
                          {/* Quantity controls */}
                          <div className="flex items-center gap-1 shrink-0">
                            <button
                              onClick={() => adjustQuantity(item.id, -item.quantity * 0.25)}
                              className="w-6 h-6 rounded-md bg-gray-100 dark:bg-white/10 flex items-center justify-center text-gray-500 hover:bg-gray-200 dark:hover:bg-white/20 transition-colors"
                            >
                              <Minus className="w-3 h-3" />
                            </button>
                            <span className="text-xs font-medium text-gray-900 dark:text-white w-12 text-center">
                              {Math.round(item.quantity)} {item.unit}
                            </span>
                            <button
                              onClick={() => adjustQuantity(item.id, item.quantity * 0.25)}
                              className="w-6 h-6 rounded-md bg-gray-100 dark:bg-white/10 flex items-center justify-center text-gray-500 hover:bg-gray-200 dark:hover:bg-white/20 transition-colors"
                            >
                              <Plus className="w-3 h-3" />
                            </button>
                          </div>
                          {/* At-home toggle */}
                          <button
                            onClick={() => toggleAtHome(item.id)}
                            className={cn(
                              'shrink-0 px-2 py-1 rounded-md text-[10px] font-medium transition-colors',
                              item.atHome
                                ? 'bg-gray-200 dark:bg-white/10 text-gray-600 dark:text-gray-400'
                                : 'bg-transparent text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'
                            )}
                          >
                            {item.atHome ? 'Have' : 'Need'}
                          </button>
                        </div>
                      ))}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </Card>
          );
        })}
      </motion.div>

      {/* Pantry Manager */}
      <motion.div
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.3, duration: 0.4, ease: [0.16, 1, 0.3, 1] as [number, number, number, number] }}
        className="mt-6"
      >
        <button
          onClick={() => setShowPantry(!showPantry)}
          className="flex items-center gap-2 text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3 hover:text-gray-900 dark:hover:text-white transition-colors"
        >
          {showPantry ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          Pantry Manager
          <span className="text-xs font-normal text-gray-400 dark:text-gray-500 ml-1">
            — staples you always have ({pantryItems.length} items)
          </span>
        </button>
        <AnimatePresence>
          {showPantry && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] as [number, number, number, number] }}
              className="overflow-hidden"
            >
              <Card className="border-gray-200 dark:border-white/5 bg-white dark:bg-[#141414]">
                <CardContent className="p-4">
                  {/* Add pantry item */}
                  <div className="flex gap-2 mb-4">
                    <Input
                      placeholder="Add pantry staple (e.g. Soy Sauce, Cooking Oil, Rice...)"
                      value={newPantryName}
                      onChange={(e) => setNewPantryName(e.target.value)}
                      onKeyDown={(e) => { if (e.key === 'Enter') addPantryItem(); }}
                      className="flex-1 bg-gray-50 dark:bg-white/5 border-gray-200 dark:border-white/10"
                    />
                    <select
                      value={newPantryCategory}
                      onChange={(e) => setNewPantryCategory(e.target.value as ShoppingCategory)}
                      className="px-3 py-2 rounded-md border border-gray-200 dark:border-white/10 bg-gray-50 dark:bg-white/5 text-sm text-gray-900 dark:text-white"
                    >
                      {CATEGORIES.map((c) => (
                        <option key={c} value={c}>{CATEGORY_CONFIG[c].label}</option>
                      ))}
                    </select>
                    <Button onClick={addPantryItem} size="sm" className="bg-[#00AEEF] hover:bg-[#008DC4] text-white">
                      <Plus className="w-4 h-4" />
                    </Button>
                  </div>

                  {/* Default pantry suggestions */}
                  {pantryItems.length === 0 && (
                    <div className="flex flex-wrap gap-2 mb-3">
                      {['Soy Sauce', 'Cooking Oil', 'Salt', 'Sugar', 'White Pepper', 'Oyster Sauce', 'Sesame Oil', 'Cornstarch', 'Rice', 'Garlic'].map(
                        (suggestion) => (
                          <button
                            key={suggestion}
                            onClick={() => {
                              setNewPantryName(suggestion);
                              setNewPantryCategory('pantry');
                            }}
                            className="text-xs px-2.5 py-1 rounded-full bg-gray-100 dark:bg-white/5 text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-white/10 transition-colors"
                          >
                            + {suggestion}
                          </button>
                        )
                      )}
                    </div>
                  )}

                  {/* Pantry list */}
                  <div className="flex flex-wrap gap-2">
                    {pantryItems.map((item) => (
                      <Badge
                        key={item.id}
                        variant="outline"
                        className="pl-2.5 pr-1 py-1.5 h-auto border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-300 flex items-center gap-1"
                      >
                        {item.name}
                        <button
                          onClick={() => removePantryItem(item.id)}
                          className="ml-1 text-gray-400 hover:text-red-500 transition-colors"
                        >
                          <Trash2 className="w-3 h-3" />
                        </button>
                      </Badge>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </div>
  );
}
