import { create } from 'zustand';

export interface MealEntry {
  id: string;
  name: string;
  mealType: string;
  foods: FoodEntry[];
  calories: number;
  protein: number;
  carbs: number;
  fats: number;
  fiber: number;
  timestamp: string;
  servings: number;
}

export interface FoodEntry {
  id: string;
  name: string;
  portion: string;
  calories: number;
  protein: number;
  carbs: number;
  fats: number;
  quantity?: number;
  unit?: string;
  fiber?: number;
  servings?: number;
  timestamp?: string;
}

export interface NutritionLog {
  id: string;
  clientId: string;
  date: string;
  meals: MealEntry[];
  waterIntake: number;
  notes: string;
}

export interface NutritionTarget {
  calories: number;
  protein: number;
  carbs: number;
  fats: number;
  waterIntake: number;
}

export type ActivityLevel = 'sedentary' | 'light' | 'moderate' | 'active' | 'very-active';

/** Macro preset string identifiers used by UI components */
export type MacroPreset = 'balanced' | 'low-carb' | 'high-protein' | 'keto' | string;

export interface StreakData {
  currentStreak: number;
  longestStreak: number;
}

export interface DailyLog {
  id: string;
  date: string;
  meals: MealEntry[];
  waterIntake: number;
  notes: string;
}

interface TDEEHistoryEntry {
  tdee: number;
  bmr: number;
  date: string;
}

interface BodyStats {
  weight: number;
  height: number;
  age: number;
  gender: 'male' | 'female';
  bodyFat: number | null;
  activityLevel: ActivityLevel;
}

interface ShoppingItem {
  name: string;
  quantity: string;
  category: string;
  checked: boolean;
}

export const MACRO_PRESETS: MacroPreset[] = [
  'balanced',
  'low-carb',
  'high-protein',
  'keto',
];

interface NutritionState {
  /* -- daily logs -- */
  logs: NutritionLog[];
  dailyLogs: DailyLog[];
  targets: Record<string, NutritionTarget>;
  bodyStats: BodyStats;
  tdee: number;
  bmr: number;
  tdeeHistory: TDEEHistoryEntry[];
  tdeeMethod: 'mifflin' | 'katch';
  calorieTarget: number;
  calorieGoal: number;
  macroTargets: NutritionTarget;
  weight: number;
  height: number;
  gender: 'male' | 'female';
  age: number;
  bodyFat: number | null;
  activityLevel: ActivityLevel;
  goalType: 'lose' | 'maintain' | 'gain';
  macroPreset: MacroPreset;
  streaks: StreakData;
  addLog: (log: Omit<NutritionLog, 'id'>) => void;
  updateLog: (id: string, data: Partial<NutritionLog>) => void;
  getLogsForClient: (clientId: string) => NutritionLog[];
  setTarget: (clientId: string, target: NutritionTarget) => void;
  getTarget: (clientId: string) => NutritionTarget | undefined;
  setBodyStats: (stats: Partial<BodyStats> & Record<string, any>) => void;
  calculateTDEE: () => number;
  computeMacroTargets: (preset: MacroPreset) => NutritionTarget;
  adjustMacroPercentages: (macro: 'protein' | 'carbs' | 'fats', delta: number) => void;
  generateMealPlan: (dayOfWeek: string) => any;
  calculateMacroScore: () => { score: number; suggestions: string[] };
  getMealLogTotals: () => { calories: number; protein: number; carbs: number; fats: number; water: number };
  setCalorieTarget: (target: number) => void;
  setMacroTargets: (targets: NutritionTarget) => void;
  generateShoppingList: () => ShoppingItem[];
  selectedDate?: string;
  setSelectedDate?: (date: string) => void;
  /* -- new actions required by pages -- */
  setGoalType: (goal: 'lose' | 'maintain' | 'gain') => void;
  setMacroPreset: (preset: MacroPreset) => void;
  setCustomMacros: (macros: { protein: number; carbs: number; fats: number }) => void;
  removeMealEntry: (date: string, mealId: string) => void;
  generateDemoData: () => void;
}

export const useNutritionStore = create<NutritionState>()((set, get) => ({
  logs: [],
  dailyLogs: [],
  targets: {},
  weight: 70,
  height: 170,
  gender: 'male',
  age: 30,
  bodyFat: null,
  activityLevel: 'moderate',
  calorieTarget: 2500,
  calorieGoal: 2500,
  macroTargets: { calories: 2500, protein: 180, carbs: 280, fats: 80, waterIntake: 3 },
  bodyStats: {
    weight: 70,
    height: 170,
    age: 30,
    gender: 'male',
    bodyFat: null,
    activityLevel: 'moderate',
  },
  tdee: 2500,
  bmr: 0,
  tdeeHistory: [],
  tdeeMethod: 'mifflin',
  goalType: 'maintain',
  macroPreset: 'balanced',
  streaks: { currentStreak: 5, longestStreak: 12 },

  addLog: (log) => {
    const id = `nut_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
    set((state) => ({ logs: [{ ...log, id }, ...state.logs] }));
  },

  updateLog: (id, data) => {
    set((state) => ({
      logs: state.logs.map((l) => (l.id === id ? { ...l, ...data } : l)),
    }));
  },

  getLogsForClient: (clientId) => {
    return get().logs.filter((l) => l.clientId === clientId);
  },

  setTarget: (clientId, target) => {
    set((state) => ({
      targets: { ...state.targets, [clientId]: target },
    }));
  },

  getTarget: (clientId) => {
    return get().targets[clientId];
  },

  setBodyStats: (stats) => {
    set((state) => {
      const newStats = { ...state.bodyStats, ...stats };
      const bmr = newStats.gender === 'male'
        ? 10 * newStats.weight + 6.25 * newStats.height - 5 * newStats.age + 5
        : 10 * newStats.weight + 6.25 * newStats.height - 5 * newStats.age - 161;
      const activityMultipliers: Record<ActivityLevel, number> = {
        sedentary: 1.2,
        light: 1.375,
        moderate: 1.55,
        active: 1.725,
        'very-active': 1.9,
      };
      const tdee = Math.round(bmr * (activityMultipliers[newStats.activityLevel] || 1.55));
      return {
        bodyStats: newStats,
        weight: newStats.weight,
        height: newStats.height,
        gender: newStats.gender,
        age: newStats.age,
        bodyFat: newStats.bodyFat,
        activityLevel: newStats.activityLevel,
        tdee,
        bmr,
        calorieTarget: tdee,
        calorieGoal: tdee,
        tdeeHistory: [...state.tdeeHistory, { tdee, bmr, date: new Date().toISOString() }].slice(-10),
        tdeeMethod: newStats.bodyFat && newStats.bodyFat > 0 ? 'katch' : 'mifflin',
      };
    });
  },

  calculateTDEE: () => {
    const state = get();
    const { bodyStats } = state;
    const bmr = bodyStats.gender === 'male'
      ? 10 * bodyStats.weight + 6.25 * bodyStats.height - 5 * bodyStats.age + 5
      : 10 * bodyStats.weight + 6.25 * bodyStats.height - 5 * bodyStats.age - 161;
    const activityMultipliers: Record<ActivityLevel, number> = {
      sedentary: 1.2,
      light: 1.375,
      moderate: 1.55,
      active: 1.725,
      'very-active': 1.9,
    };
    const tdee = Math.round(bmr * (activityMultipliers[bodyStats.activityLevel] || 1.55));
    set({
      tdee,
      bmr,
      calorieTarget: tdee,
      calorieGoal: tdee,
      tdeeHistory: [...state.tdeeHistory, { tdee, bmr, date: new Date().toISOString() }].slice(-10),
      tdeeMethod: bodyStats.bodyFat && bodyStats.bodyFat > 0 ? 'katch' : 'mifflin',
    });
    return tdee;
  },

  computeMacroTargets: (preset) => {
    const state = get();
    const cals = state.calorieTarget || state.tdee;
    let proteinPercent = 30, carbsPercent = 40, fatsPercent = 30;
    if (preset === 'low-carb') { proteinPercent = 35; carbsPercent = 25; fatsPercent = 40; }
    else if (preset === 'high-protein') { proteinPercent = 40; carbsPercent = 30; fatsPercent = 30; }
    else if (preset === 'keto') { proteinPercent = 25; carbsPercent = 5; fatsPercent = 70; }
    const protein = Math.round((cals * (proteinPercent / 100)) / 4);
    const carbs = Math.round((cals * (carbsPercent / 100)) / 4);
    const fats = Math.round((cals * (fatsPercent / 100)) / 9);
    return { calories: cals, protein, carbs, fats, waterIntake: state.macroTargets.waterIntake };
  },

  adjustMacroPercentages: (macro, delta) => {
    set((state) => {
      const currentGrams = state.macroTargets[macro];
      const newGrams = Math.max(0, currentGrams + delta);
      const newTargets = { ...state.macroTargets, [macro]: newGrams };
      return { macroTargets: newTargets };
    });
  },

  generateMealPlan: (dayOfWeek) => {
    return { dayOfWeek, meals: [] };
  },

  calculateMacroScore: () => {
    return { score: 85, suggestions: ['Increase protein intake', 'Reduce fat intake'] };
  },

  getMealLogTotals: () => {
    const state = get();
    const todayLog = state.logs[0];
    if (!todayLog) return { calories: 0, protein: 0, carbs: 0, fats: 0, water: 0 };
    return todayLog.meals.reduce(
      (acc, m) => ({
        calories: acc.calories + (m.calories || 0),
        protein: acc.protein + (m.protein || 0),
        carbs: acc.carbs + (m.carbs || 0),
        fats: acc.fats + (m.fats || 0),
        water: todayLog.waterIntake || 0,
      }),
      { calories: 0, protein: 0, carbs: 0, fats: 0, water: 0 }
    );
  },

  setCalorieTarget: (target) => {
    set({ calorieTarget: target, calorieGoal: target });
  },

  setMacroTargets: (targets) => {
    set({ macroTargets: targets });
  },

  generateShoppingList: () => {
    return [];
  },

  /* -- New actions -- */
  setGoalType: (goalType) => {
    set((state) => {
      const delta = goalType === 'lose' ? -500 : goalType === 'gain' ? 300 : 0;
      const calorieGoal = state.tdee + delta;
      return { goalType, calorieGoal, calorieTarget: calorieGoal };
    });
  },

  setMacroPreset: (preset) => {
    set((state) => {
      const targets = state.computeMacroTargets(preset);
      return { macroPreset: preset, macroTargets: targets };
    });
  },

  setCustomMacros: ({ protein, carbs, fats }) => {
    set((state) => ({
      macroTargets: {
        ...state.macroTargets,
        protein,
        carbs,
        fats,
        calories: protein * 4 + carbs * 4 + fats * 9,
      },
      macroPreset: 'custom',
    }));
  },

  removeMealEntry: (date, mealId) => {
    set((state) => ({
      dailyLogs: state.dailyLogs.map((log) =>
        log.date === date
          ? { ...log, meals: log.meals.filter((m) => m.id !== mealId) }
          : log
      ),
    }));
  },

  generateDemoData: () => {
    const today = new Date().toISOString().split('T')[0];
    const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];
    const demoLogs: DailyLog[] = [
      {
        id: `demo_1`,
        date: today,
        waterIntake: 5,
        notes: '',
        meals: [
          {
            id: 'm1', name: 'Oatmeal & Banana', mealType: 'breakfast', foods: [],
            calories: 350, protein: 12, carbs: 58, fats: 6, fiber: 8,
            timestamp: `${today}T08:00:00`, servings: 1,
          },
          {
            id: 'm2', name: 'Chicken Rice', mealType: 'lunch', foods: [],
            calories: 550, protein: 35, carbs: 68, fats: 14, fiber: 3,
            timestamp: `${today}T12:30:00`, servings: 1,
          },
          {
            id: 'm3', name: 'Salmon & Vegetables', mealType: 'dinner', foods: [],
            calories: 480, protein: 38, carbs: 22, fats: 26, fiber: 6,
            timestamp: `${today}T19:00:00`, servings: 1,
          },
        ],
      },
      {
        id: `demo_2`,
        date: yesterday,
        waterIntake: 6,
        notes: '',
        meals: [
          {
            id: 'm4', name: 'Protein Shake', mealType: 'breakfast', foods: [],
            calories: 180, protein: 30, carbs: 5, fats: 4, fiber: 1,
            timestamp: `${yesterday}T07:30:00`, servings: 1,
          },
          {
            id: 'm5', name: 'Beef Stir Fry', mealType: 'lunch', foods: [],
            calories: 620, protein: 42, carbs: 55, fats: 24, fiber: 5,
            timestamp: `${yesterday}T12:00:00`, servings: 1,
          },
        ],
      },
    ];
    set({ dailyLogs: demoLogs, streaks: { currentStreak: 5, longestStreak: 12 } });
  },
}));

export type { NutritionState };
